<?php namespace App\Models; use Illuminate\Database\Eloquent\Model; class Transaksi extends Model {protected $fillable=['pelanggan_id','tanggal_masuk','tanggal_selesai','total','status']; protected $casts=['tanggal_masuk'=>'datetime','tanggal_selesai'=>'datetime']; public function pelanggan(){return $this->belongsTo(Pelanggan::class);} public function details(){return $this->hasMany(DetailTransaksi::class);} public function pembayaran(){return $this->hasOne(Pembayaran::class);}}
